/**
 * Enqueue worker service for ecommerce.NotificationService (rabbitmq).
 * Consumes queue messages and dispatches to the per-handler
 * workers/*.handler.ts modules, resolving MikroORM EntityManager /
 * EventEmitter2 via Nest DI instead of manual MikroORM.init()/new EventEmitter2().
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import { Injectable, Logger } from '@nestjs/common';
import amqplib from 'amqplib';
import { EntityManager } from '@mikro-orm/core';
import { handleSendOrderConfirmation } from './send-order-confirmation.handler';

const QUEUE_SEND_ORDER_CONFIRMATION = 'order-service.send-order-confirmation';

@Injectable()
export class EnqueueWorkerService {
  private readonly logger = new Logger(EnqueueWorkerService.name);
  private shutdownRequested = false;

  constructor(
    private readonly em: EntityManager,
  ) {}

  async start(): Promise<void> {
    this.logger.log('enqueue_worker_starting service=notification-service engine=rabbitmq');
    await this._startRabbitMq();
  }

  private async _startRabbitMq(): Promise<void> {
    const amqpUrl = process.env.QUEUE_AMQP_URL;
    if (!amqpUrl) {
      throw new Error('QUEUE_AMQP_URL environment variable is required');
    }
    const connection = await amqplib.connect(amqpUrl);
    const channel = await connection.createChannel();
    await channel.prefetch(
      parseInt(
        process.env['QUEUE_SEND_ORDER_CONFIRMATION_CONCURRENCY'] ?? '5',
        10,
      ),
    );
    await channel.assertQueue(QUEUE_SEND_ORDER_CONFIRMATION, { durable: true });
    await channel.consume(QUEUE_SEND_ORDER_CONFIRMATION, (msg) => {
      if (msg) {
        const em = this.em.fork();
        void handleSendOrderConfirmation(msg, channel, em).catch((err) => {
          const message = err instanceof Error ? err.message : String(err);
          this.logger.error(`handler_rejected queue=send-order-confirmation error=${message}`);
        });
      }
    });

    const queueList = ['send-order-confirmation'].join(',');
    this.logger.log(`enqueue_worker_ready service=notification-service queues=${queueList}`);

    const shutdown = async (signal: string): Promise<void> => {
      this.logger.log(`shutdown_signal_received signal=${signal}`);
      this.shutdownRequested = true;
      await channel.close();
      await connection.close();
      this.logger.log('enqueue_worker_stopped service=notification-service');
      process.exit(0);
    };
    process.on('SIGTERM', () => {
      void shutdown('SIGTERM');
    });
    process.on('SIGINT', () => {
      void shutdown('SIGINT');
    });
  }
}
